Item.method_code:
if(value !== true)
{
    return;
}
const item = aras.itemsCache.getItemByXPath("//Item[@id='"+itemId+"']");
const isTemp = item.getAttribute("isTemp");

if(isTemp !== "1" )
{
    const title = aras.getResource('', 'common.warning');
    const okButtonText = aras.getResource('', 'confirm_delete.delete_all');
    const options = {
        title,
        okButtonText
    };
    const propertyName = aras.getItemProperty(item,'name');
    return ArasModules.Dialog.confirm(aras.getResource('', 'ui_methods_ex.changing_to_federated_delete_all_values', propertyName), options).then(function (result) {
                if (result !== 'ok') {
                    aras.setItemProperty(item, 'is_federated', '0');
                }
            });
}
